function deadlineCard({p,d},timeline=false){const status=deadlinePresentation(d),parts=status.label.match(/^(.*?)(\d+)(.*)$/),remaining=parts?`${esc(parts[1])}<b>${parts[2]}</b>${esc(parts[3])}`:esc(status.label);return `<div class="${timeline?'timeline-node':'deadline-row'} deadline-card is-${status.tone}" ${timeline&&d.done&&!projectDeadlineShowDone?'hidden':''} style="--deadline-color:${esc(p.color)}"><strong class="deadline-state">${remaining}</strong><div class="deadline-surface"><time datetime="${d.date}" title="${d.date}"><strong>${Number(d.date.slice(5,7))}.${Number(d.date.slice(8))}</strong><small>${d.date.slice(0,4)}</small></time><div class="${timeline?'timeline-content':'deadline-content'}"><div class="deadline-card-heading"><button data-edit-deadline="${d.id}" data-project-id="${p.id}" title="${esc(projectLabel(p)+' · '+d.name+(d.note?'\n'+d.note:''))}" class="${d.done?'completed-text':''}">${esc(d.name)}</button>${d.note?.trim()?`<div class="deadline-inline-note markdown-body" aria-label="节点备注" title="${esc(d.note)}">${renderMarkdown(d.note)}</div>`:''}<input type="checkbox" data-deadline-check="${d.id}" data-project-id="${p.id}" ${d.done?'checked':''} aria-label="${esc(d.name)}标记完成"></div><div class="deadline-meta">${timeline?'':`<span class="deadline-project" title="${esc(projectLabel(p))}">${esc(p.name)}</span>`}<span class="priority-badge ${d.priority==='高'?'priority-high':''}">${esc(d.priority)}优先</span></div></div></div></div>`}
