function renderProjectList(){const visible=orderedProjects();$('#project-sort').value=state.settings.projectSort||'manual';$('#sort-projects').hidden=(state.settings.projectSort||'manual')!=='manual';$('#sort-projects').textContent=sortMode?'完成排序':'排序';$('#sort-projects').setAttribute('aria-pressed',sortMode);mountProjectList($('#project-list'),visible,{groups:state.settings.projectGroups||[],row:p=>{const peers=visible.filter(x=>projectGroup(x)===projectGroup(p)&&!!x.completed===!!p.completed),i=peers.findIndex(x=>x.id===p.id);const m=summarize(state.entries.filter(e=>e.projectId===p.id),estimates());return `<div class="project-list-row"><button class="project-item ${p.id===currentProject?'active':''}" data-select-project="${p.id}"><strong><i class="project-dot" style="--project-color:${p.color}"></i>${esc(p.name)}</strong><small>${fmt(m.total)}h${m.estimated?' 含估算':''} · ${m.count} 天${p.completed?' · 已完成':''}</small></button>${sortMode?`<div class="sort-arrows"><button data-sort-id="${p.id}" data-sort-target="${peers[i-1]?.id||''}" ${!i?'disabled':''} aria-label="上移 ${esc(p.name)}">↑</button><button data-sort-id="${p.id}" data-sort-target="${peers[i+1]?.id||''}" data-after="true" ${i===peers.length-1?'disabled':''} aria-label="下移 ${esc(p.name)}">↓</button></div>`:''}</div>`},bind:()=>{$$('[data-select-project]').forEach(b=>b.onclick=async()=>{if(!await leaveDirtyNote())return;currentProject=b.dataset.selectProject;noteDirty=false;renderProjects()});$$('[data-sort-id]').forEach(b=>b.onclick=async()=>{if(!await leaveDirtyNote())return;const next=clone(state);next.projects=reorderProjects(next.projects,b.dataset.sortId,b.dataset.sortTarget,b.dataset.after==='true');await commit(next)})}})}
function dailyRecordsHTML(entries){if(!entries.length)return '<p class="empty">还没有每日记录。</p>';const months=[...new Set(entries.map(e=>e.date.slice(0,7)))];return months.map(month=>{const list=entries.filter(e=>e.date.startsWith(month)),total=summarize(list,estimates());return `<section class="daily-month"><div class="daily-month-heading"><span>${Number(month.slice(0,4))} 年 ${Number(month.slice(5))} 月</span><small>${list.length} 天 · ${fmt(total.total)}h${total.estimated?' 含估算':''}</small></div><div class="daily-month-records">${list.map(e=>{const date=parseDate(e.date),weekday=new Intl.DateTimeFormat('zh-CN',{weekday:'short'}).format(date);return `<button class="daily-card daily-record-row" data-edit-entry="${e.date}" aria-label="编辑 ${e.date} 的记录"><time datetime="${e.date}"><strong>${date.getDate()}</strong><small>${weekday}</small></time><div class="markdown-body daily-note ${e.note?'':'is-empty'}">${renderMarkdown(e.note||'当天未填写备注')}</div><strong class="daily-duration">${esc(entryLabel(e))}</strong><span class="daily-open" aria-hidden="true">›</span></button>`}).join('')}</div></section>`}).join('')}
