window.addEventListener('keydown',e=>{if(!(e.ctrlKey||e.metaKey)||e.altKey)return;const edit=e.target.closest('input,textarea,[contenteditable=true]');if(edit||document.querySelector('dialog[open]'))return;const key=e.key.toLowerCase();if(key==='z'||key==='y'){e.preventDefault();if(!state?.history)return;stepHistory(key==='y'||e.shiftKey?1:-1)}});

document.addEventListener('click',e=>{const path=e.composedPath();$$('details[open]:not(.fold-panel):not(.auto-project-types):not([data-ui-panel])').forEach(d=>{if(!path.includes(d))d.open=false})});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]'))$$('details[open]:not(.fold-panel):not(.auto-project-types):not([data-ui-panel])').forEach(d=>d.open=false)});

document.addEventListener('click',async e=>{const time=e.target.closest('[data-clear-time]'),note=e.target.closest('[data-clear-note]');if(time){$('#'+time.dataset.clearTime+'-clear-time').click();flushDrafts()}if(note){const field=$('#'+note.dataset.clearNote);if(isDesktopHost()&&['inspector-note','record-note'].includes(field.id)){e.preventDefault();if(!await confirmAction('清除当日备注','将清除当前项目这一天的备注，已记录的时长会保留。'))return}field.value='';field.dispatchEvent(new Event('input',{bubbles:true}));flushDrafts()}});

window.journalStepHistory=stepHistory;

function groupRow(name=''){const count=state.projects.filter(p=>projectGroup(p)===name).length;return `<div class="group-edit-row" data-original="${esc(name)}"><input class="group-name-input" value="${esc(name)}" maxlength="60" aria-label="分组名称" placeholder="例如：科研、申报、报告"><small>${name?count+' 个项目':'新分组'}</small><span class="group-order-buttons"><button type="button" class="quiet" data-group-move="-1" aria-label="上移分组">↑</button><button type="button" class="quiet" data-group-move="1" aria-label="下移分组">↓</button></span><button type="button" class="quiet remove-group" aria-label="移除分组">×</button></div>`}
function wireGroupRows(){const rows=$$('#groups-list .group-edit-row');rows.forEach((row,i)=>{row.querySelector('.remove-group').onclick=()=>{row.remove();wireGroupRows()};row.querySelectorAll('[data-group-move]').forEach(button=>{const delta=Number(button.dataset.groupMove);button.disabled=i+delta<0||i+delta>=rows.length;button.onclick=()=>{const target=rows[i+delta];if(delta<0)target.before(row);else target.after(row);wireGroupRows();row.querySelector('input').focus()}})})}
$('#manage-groups').onclick=async()=>{if(!await flushDrafts())return;$('#groups-list').innerHTML=projectGroups(state.projects,state.settings.projectGroups||[]).filter(Boolean).map(groupRow).join('')||groupRow();wireGroupRows();$('#groups-dialog').showModal()};
$('#add-group-row').onclick=()=>{$('#groups-list').insertAdjacentHTML('beforeend',groupRow());wireGroupRows();$$('#groups-list input').at(-1).focus()};
$('#groups-form').onsubmit=async e=>{e.preventDefault();const names=[],rename=new Map();for(const row of $$('#groups-list .group-edit-row')){const name=row.querySelector('input').value.trim();if(!name)continue;if(names.includes(name)){toast('分组名称不能重复',true);return}names.push(name);if(row.dataset.original)rename.set(row.dataset.original,name)}const next=clone(state);next.settings.projectGroups=names;for(const p of next.projects){if(projectGroup(p))p.group=rename.get(projectGroup(p))||''}if(await commit(next)){$('#groups-dialog').close();toast('分组已保存')}};

for(const id of ['distribution-by-group','deadline-by-group']){const button=$('#'+id);paintGroupingButton(id);button.onclick=async e=>{e.preventDefault();e.stopPropagation();const active=button.getAttribute('aria-pressed')!=='true';if(id==='distribution-by-group'){if(!await flushDrafts())return;const next=clone(state);next.settings[distributionGroupingKey()]=active;await commit(next)}else{uiPreferences.setFlag('deadlineGrouped',active);button.setAttribute('aria-pressed',String(active));button.classList.toggle('active',active);renderUpcoming()}}}

window.journalSaveNote=async input=>{if(input?.id==='deadline-note')return saveDeadline(false);if(input?.classList.contains('auto-note'))return automationUI.flush();return flushDrafts()};
setupMarkdownEditors();if(isDesktopHost())refineDesktopNotes();

// Escape consumes one interaction layer, leaving saved records and drafts intact.
document.addEventListener('keydown',e=>{
 if(e.key!=='Escape'||e.isComposing)return;
 const modal=document.querySelector('dialog[open]'),scope=modal||document;
 const menus=[...scope.querySelectorAll('details[open]:not(.fold-panel):not(.auto-project-types):not([data-ui-panel])')];
 const consume=()=>{e.preventDefault();e.stopImmediatePropagation()};
 if(menus.length){consume();const menu=menus.at(-1);menu.open=false;menu.querySelector('summary')?.focus({preventScroll:true});return}
 // Keep each dialog's existing cancel/save handling and block underlying page handlers.
 if(modal){e.stopImmediatePropagation();return}
 if(calendarGesture){consume();finishCalendarGesture(true);return}
 if(page==='auto'){consume();automationUI?.cancelSelection();return}
 consume();hideTooltip();window.getSelection()?.removeAllRanges();document.activeElement?.blur();
 if(page==='review'){void(async()=>{if(!await leaveInspector())return;batch=false;selected.clear();anchor=null;reviewDeselected=true;inspectedExplicit=false;renderBatch();renderInspector(true)})()}
 if(page==='projects'){void(async()=>{if(!await leaveDirtyNote())return;currentProject=null;sortMode=false;renderProjects()})()}
},true);
